macro_rules! deps {
    () => {
        ConstCx!();
    };
}

macro_rules! Qualif {
    () => {
        deps!();
        # [doc = " A \"qualif\"(-ication) is a way to look for something \"bad\" in the MIR that would disqualify some"] # [doc = " code for promotion or prevent it from evaluating at compile time."] # [doc = ""] # [doc = " Normally, we would determine what qualifications apply to each type and error when an illegal"] # [doc = " operation is performed on such a type. However, this was found to be too imprecise, especially"] # [doc = " in the presence of `enum`s. If only a single variant of an enum has a certain qualification, we"] # [doc = " needn't reject code unless it actually constructs and operates on the qualified variant."] # [doc = ""] # [doc = " To accomplish this, const-checking and promotion use a value-based analysis (as opposed to a"] # [doc = " type-based one). Qualifications propagate structurally across variables: If a local (or a"] # [doc = " projection of a local) is assigned a qualified value, that local itself becomes qualified."] pub trait Qualif { # [doc = " The name of the file used to debug the dataflow analysis that computes this qualif."] const ANALYSIS_NAME : & 'static str ; # [doc = " Whether this `Qualif` is cleared when a local is moved from."] const IS_CLEARED_ON_MOVE : bool = false ; # [doc = " Whether this `Qualif` might be evaluated after the promotion and can encounter a promoted."] const ALLOW_PROMOTED : bool = false ; # [doc = " Extracts the field of `ConstQualifs` that corresponds to this `Qualif`."] fn in_qualifs (qualifs : & ConstQualifs) -> bool ; # [doc = " Returns `true` if *any* value of the given type could possibly have this `Qualif`."] # [doc = ""] # [doc = " This function determines `Qualif`s when we cannot do a value-based analysis. Since qualif"] # [doc = " propagation is context-insensitive, this includes function arguments and values returned"] # [doc = " from a call to another function."] # [doc = ""] # [doc = " It also determines the `Qualif`s for primitive types."] fn in_any_value_of_ty < 'tcx > (cx : & ConstCx < '_ , 'tcx > , ty : Ty < 'tcx >) -> bool ; # [doc = " Returns `true` if the `Qualif` is structural in an ADT's fields, i.e. if we may"] # [doc = " recurse into an operand *value* to determine whether it has this `Qualif`."] # [doc = ""] # [doc = " If this returns false, `in_any_value_of_ty` will be invoked to determine the"] # [doc = " final qualif for this ADT."] fn is_structural_in_adt_value < 'tcx > (cx : & ConstCx < '_ , 'tcx > , adt : AdtDef < 'tcx >) -> bool ; }
    };
}

Qualif!()